export STATE_DIR="$(mktemp -d)/state" && node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import path from 'node:path';
const botPath = path.resolve(process.cwd(), 'bot.mjs');
const { reserve } = await import(botPath);
const base = new Date('2026-10-23T10:00:00Z');
const at = (min) => new Date(base.getTime() + min * 60000);
const checks = [];
const ok = (name, cond, extra = '') => checks.push([name, !!cond, extra]);

// Sequential: 5 allowed over mixed channels, 6th blocked
const chans = ['sms', 'push', 'chat', 'sms', 'push'];
const first = [];
for (let i = 0; i < 5; i++) first.push(await reserve('cust-a', chans[i], at(i)));
ok('5 allowed', first.every((r) => r.allowed && r.retryAt === null));
const six = await reserve('cust-a', 'chat', at(6));
ok('6th blocked', !six.allowed && six.retryAt);
ok('retryAt = oldest + 24h', six.retryAt && six.retryAt.getTime() === at(0).getTime() + 86400000, String(six.retryAt));
ok('reason is a sentence', six.reason.includes('5 proactive') && six.reason.includes('24 hours'));
// Refused calls do not count
const again = await reserve('cust-a', 'sms', at(7));
ok('refusal not counted', !again.allowed && again.retryAt.getTime() === six.retryAt.getTime());
// Just before retryAt still blocked; at retryAt allowed
ok('blocked 1ms before retryAt', !(await reserve('cust-a', 'sms', new Date(six.retryAt.getTime() - 1))).allowed);
ok('allowed at retryAt', (await reserve('cust-a', 'sms', six.retryAt)).allowed);
// Isolation: other customer unaffected
ok('other customer allowed', (await reserve('cust-b', 'sms', at(6))).allowed);

// Parallel: 12 processes race for the same customer at the same instant
const child = `const {reserve}=await import(process.env.BOT_PATH);const r=await reserve('race-user','sms',new Date('2026-10-23T12:00:00Z'));console.log(JSON.stringify(r));`;
const runOne = () => new Promise((resolve, reject) => {
  const p = spawn(process.execPath, ['--input-type=module', '-e', child], { env: { ...process.env, BOT_PATH: botPath } });
  let out = ''; let err = '';
  p.stdout.on('data', (d) => (out += d)); p.stderr.on('data', (d) => (err += d));
  p.on('close', (code) => (code === 0 ? resolve(JSON.parse(out.trim().split('\n').pop())) : reject(new Error(err))));
});
const results = await Promise.all(Array.from({ length: 12 }, runOne));
const allowedCount = results.filter((r) => r.allowed).length;
ok('parallel: exactly 5 of 12 allowed', allowedCount === 5, `allowed=${allowedCount}`);

for (const c of checks) console.log(c[1] ? 'PASS' : 'FAIL', c[0], c[2]);
console.log(checks.every((c) => c[1]) ? 'ALL PASS' : 'SOME FAILED');
EOF
echo "exit=$?"; ls "$STATE_DIR/users" | head; echo "lock dirs left: $(find "$STATE_DIR" -name '*.lock' | wc -l)"
